				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$\begin{aligned}&\mathrm{S}\text{-Osmolalit{\"a}t}_{\mathrm{calc}}\left(\frac{\text{mOsmol}}{\text{kg}}\right)=\\ &1{,}86x\text{S-Na}\,\left(\frac{\text{mmol}}{\text{l}}\right)+\frac{\text{S-BUN}\,\left(\frac{\text{mg}}{\text{dl}}\right)}{2{,}8}+\\ &\frac{\mathrm{S}\text{-Glukose}\,\left(\frac{\text{mg}}{\text{dl}}\right)}{18}+9\end{aligned}$$\end{document}S-OsmolalitätcalcmOsmolkg=1,86xS-Nammoll+S-BUNmgdl2,8+S-Glukosemgdl18+9

